local sources, paths = {}, {}
local manifest = [=[engine	engine	9986
flimg	flimg	19681
core.ai	core/ai	5127
core.audio	core/audio	2551
core.buffer	core/buffer	21016
core.camera	core/camera	4432
core.color	core/color	5177
core.console	core/console	4359
core.db	core/db	3671
core.debug	core/debug	170
core.ecs	core/ecs	4390
core.error	core/error	1695
core.event	core/event	738
core.input	core/input	4340
core.input_mapper	core/input_mapper	548
core.loader	core/loader	4383
core.logger	core/logger	1182
core.math	core/math	2966
core.network	core/network	9390
core.particles	core/particles	3757
core.pathfinding	core/pathfinding	3641
core.physics	core/physics	2859
core.scene	core/scene	18459
core.serialization	core/serialization	2850
core.server	core/server	13613
core.storage	core/storage	1033
core.thread	core/thread	1955
core.tilemap	core/tilemap	5069
core.timer	core/timer	3014
core.tween	core/tween	7030
core.ui.element	core/ui/element	2152
core.ui.events	core/ui/events	5469
core.ui	core/ui/init	4307
core.ui.render	core/ui/render	6728]=]
local offset = 1
for line in manifest:gmatch("[^\n]+") do
    local name, path, size = line:match("^(.-)\t(.-)\t(%d+)$")
    size = tonumber(size)
    sources[name] = payload:sub(offset, offset + size - 1)
    paths[name] = path
    offset = offset + size
end
local loaded = {}
local loading = {}
local function loader(name)
    local cached = loaded[name]
    if cached ~= nil then return cached end
    if loading[name] then
        error("Obsidian: circular require of " .. tostring(name), 0)
    end
    print("Loading module: " .. name)
    local source = sources[name]
        or error("Obsidian: module not bundled: " .. tostring(name), 0)
    -- Same contract as src/init.lua: modules run in the caller's environment,
    -- so CraftOS-provided globals such as shell stay visible to them.
    local chunk = assert(load(source,
        "@obsidian/" .. (paths[name] or name) .. ".lua", nil, _ENV))
    loading[name] = true
    local result = chunk(loader, name)
    loading[name] = nil
    loaded[name] = result == nil and true or result
    return loaded[name]
end

return loader("engine")